from pathlib import Path
p = Path('src/middleware/request-id/request-id.ts')
s = p.read_text()
s = s.replace("""export type RequestIdOptions = {
  limitLength?: number
  headerName?: string
  generator?: (c: Context) => string
}""", """export type RequestIdOptions = {
  limitLength?: number
  headerName?: string
  generator?: (c: Context) => string
  trustIncoming?: boolean
}""")
s = s.replace(""" * @param {generator} [options.generator=() => crypto.randomUUID()] - The request id generation function.
""", """ * @param {generator} [options.generator=() => crypto.randomUUID()] - The request id generation function.
 * @param {boolean} [options.trustIncoming=true] - Whether to use an incoming request id header when it is valid.
""")
s = s.replace("""export const requestId = ({
  limitLength = 255,
  headerName = 'X-Request-Id',
  generator = () => crypto.randomUUID(),
}: RequestIdOptions = {}): MiddlewareHandler => {
  return async function requestId(c, next) {
    // If `headerName` is empty string, req.header will return the object
    let reqId = headerName ? c.req.header(headerName) : undefined
    if (!reqId || reqId.length > limitLength || /[^\\w\\-=]/.test(reqId)) {
      reqId = generator(c)
    }
""", """export const requestId = ({
  limitLength = 255,
  headerName = 'X-Request-Id',
  generator = () => crypto.randomUUID(),
  trustIncoming = true,
}: RequestIdOptions = {}): MiddlewareHandler => {
  return async function requestId(c, next) {
    // If `headerName` is empty string, req.header will return the object
    let reqId = trustIncoming && headerName ? c.req.header(headerName) : undefined
    if (!reqId || reqId.length > limitLength || /[^\\w\\-=]/.test(reqId)) {
      reqId = generator(c)
    }
""")
p.write_text(s)

p = Path('src/middleware/request-id/index.test.ts')
s = p.read_text()
s += """
describe('Request ID Middleware with trustIncoming', () => {
  const app = new Hono()
  app.use('/trust', requestId({ trustIncoming: true }))
  app.use('/noTrust', requestId({ trustIncoming: false }))
  app.use('/noTrustGenerator', requestId({ trustIncoming: false, generator: () => 'generated-id' }))
  app.get('/trust', (c) => c.text(c.get('requestId') ?? 'No Request ID'))
  app.get('/noTrust', (c) => c.text(c.get('requestId') ?? 'No Request ID'))
  app.get('/noTrustGenerator', (c) => c.text(c.get('requestId') ?? 'No Request ID'))

  it('Should use incoming request id header by default', async () => {
    const res = await app.request('http://localhost/trust', {
      headers: {
        'X-Request-Id': 'trusted-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('trusted-id')
    expect(await res.text()).toBe('trusted-id')
  })

  it('Should ignore incoming request id header when trustIncoming is false', async () => {
    const res = await app.request('http://localhost/noTrust', {
      headers: {
        'X-Request-Id': 'trusted-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toMatch(regexUUIDv4)
    expect(res.headers.get('X-Request-Id')).not.toBe('trusted-id')
    expect(await res.text()).toMatch(regexUUIDv4)
    expect(await res.text()).not.toBe('trusted-id')
  })

  it('Should use the configured generator when trustIncoming is false', async () => {
    const res = await app.request('http://localhost/noTrustGenerator', {
      headers: {
        'X-Request-Id': 'trusted-id',
      },
    })
    expect(res).not.toBeNull()
    expect(res.status).toBe(200)
    expect(res.headers.get('X-Request-Id')).toBe('generated-id')
    expect(await res.text()).toBe('generated-id')
  })
})
"""
p.write_text(s)
EOF
